   294	    fn reconstruct_function_node(&self, info: &FunctionInfo) -> Option<Node<'_>> {
   295	        let mut node = self
   296	            .tree
   297	            .root_node()
   298	            .descendant_for_byte_range(info.start_byte, info.end_byte)?;
   299	        // descendant_for_byte_range returns the DEEPEST node spanning the range,
   300	        // so recovery walks UP through same-span ancestors — a walk-down can
   301	        // never reach a same-span ancestor.
   302	        loop {
   303	            if node.start_byte() == info.start_byte
   304	                && node.end_byte() == info.end_byte
   305	                && node.kind_id() == info.kind_id
   306	            {
   307	                return Some(node);
   308	            }
   309	            match node.parent() {
   310	                Some(p) if p.start_byte() == info.start_byte && p.end_byte() == info.end_byte => {
   311	                    node = p
   312	                }
   313	                _ => return None,
   314	            }
   315	        }
   316	    }
