    35	        // wrappers and the inner function_definition. Wrapper kinds never survive
    36	        // over their inner definition.
    37	        let mut keep = vec![true; recs.len()];
    38	        for i in 0..recs.len() {
    39	            for j in 0..recs.len() {
    40	                if i == j {
    41	                    continue;
    42	                }
    43	                let (outer, inner) = (&recs[i], &recs[j]);
    44	                let contains = outer.start_line <= inner.start_line
    45	                    && inner.end_line <= outer.end_line
    46	                    && (outer.start_line, outer.end_line) != (inner.start_line, inner.end_line);
    47	                let wrapper = outer.kind == "decorated_definition";
    48	                if contains && wrapper {
    49	                    keep[i] = false;
    50	                }
    51	            }
    52	        }
    53	        let mut it = keep.iter();
    54	        let mut recs = recs;
    55	        recs.retain(|_| *it.next().unwrap());
