    85	/// Recovery instrument (spec §7 / review MAJOR 5). For an owner-method `T::m`
    86	/// site, report what the disproof prune ACTUALLY decided (re-derived measurement-
    87	/// only, exactly as `shadow_narrow_type_path` re-derives the narrowing — never
    88	/// read from final edge counts, which cannot tell a prune-demote from a fail-open
    89	/// demote):
    90	///   `singleton`        — the prune disproved down to a single survivor (the
    91	///                        recovered Exact: ①C+②B held and the id-set pinned one).
    92	///   `pruned_multiple`  — the prune disproved ≥1 but >1 survived (a real prune
    93	///                        that still demotes to NameOnly).
    94	///   `failopen_singleton` — the predicate proved nothing; the bare pool is a
    95	///                        singleton (the #120 floor mints Exact — not a recovery).
    96	///   `failopen_demote`  — the predicate proved nothing; the bare pool collides
    97	///                        (the #120 floor demotes to NameOnly — the un-recovered
    98	///                        residue this slice aims to shrink).
    99	///   `not_owner_method` — no bare `(owner, method)` pool / unresolvable scope.
   100	/// Keyed off the owner-`::` population, not the >=2-Exact population the legacy
   101	/// `shadow_typepath_narrow` requires.
   102	fn classify_recovery_typepath(cg: &CallGraph, site: &CallSite) -> &'static str {
   103	    use crate::name_resolution::rust_populator::enclosing_scope;
   104	    use crate::resolution::{prune, DisproofCx, DisproofPredicate, ScopeResolution};
   105	    // Owner-method key `(T, m)` from `mod::T::m` (mirror the resolver's split;
   106	    // `crate`/`super` stripped, `self`/`Self` heads excluded).
   107	    let mut segs: Vec<&str> = site.callee_name.split("::").collect();
   108	    let Some(method) = segs.pop() else {
   109	        return "not_owner_method";
   110	    };
   111	    while matches!(segs.first(), Some(&"crate") | Some(&"super")) {
   112	        segs.remove(0);
   113	    }
   114	    let Some(&owner) = segs.last() else {
   115	        return "not_owner_method";
   116	    };
   117	    if owner == "self" || owner == "Self" {
   118	        return "not_owner_method";
   119	    }
   120	    let Some(pool_ids) = cg.methods.get(&(owner.to_string(), method.to_string())) else {
   121	        return "not_owner_method";
   122	    };
   123	    // Re-derive the authoritative (file, enclosing-scope) the prune ran from. If
   124	    // the graph is absent/incomplete or the byte has no scope, this site never
   125	    // reached the prune -> not a recovery outcome.
   126	    let Some(graph) = cg.scope_graph.as_ref() else {
   127	        return "not_owner_method";
   128	    };
   129	    if !graph.complete {
   130	        return "not_owner_method";
   131	    }
   132	    let Some(file) = graph.file_paths.get(&site.caller.file).copied() else {
   133	        return "not_owner_method";
   134	    };
   135	    let Some(from) = enclosing_scope(graph, file, site.start_byte) else {
   136	        return "not_owner_method";
   137	    };
   138	    let pool: Vec<&FunctionId> = pool_ids.iter().collect();
   139	    let pred = ScopeResolution::new(cg);
   140	    let cx = DisproofCx { graph, file, from };
   141	    let kept = prune(pool.clone(), site, &cx, &[&pred as &dyn DisproofPredicate]);
   142	    if kept.len() < pool.len() {
   143	        // The predicate disproved at least one candidate (a real prune).
   144	        if kept.len() == 1 {
   145	            "singleton"
   146	        } else {
   147	            "pruned_multiple"
   148	        }
   149	    } else if pool.len() == 1 {
   150	        "failopen_singleton"
   151	    } else {
   152	        "failopen_demote"
   153	    }
   154	}
