   649	pub fn callers_with_confidence(
   650	    s: &NavigationSession,
   651	    symbol: Option<&str>,
   652	    file: Option<&str>,
   653	    location: Option<&str>,
   654	    depth: usize,
   655	    exact_only: bool,
   656	) -> Result<Evidence, QueryError> {
   657	    let resolved = seed::resolve_fn(s, symbol, file, location)?;
   658	    let target = fid_of(&resolved.symbol);
   659	    let target_for_warning = target.clone();
   660	    let query = format!("callers:{}@{}", target.name, target.file); // @file identity (R3-M4)
   661	    let mut items = Vec::new();
   662	    let mut visited: std::collections::BTreeSet<FunctionId> = std::collections::BTreeSet::new();
   663	    visited.insert(target.clone());
   664	    let mut frontier = vec![target];
   665	    for hop in 0..depth {
   666	        // hop 0 = direct hit → score 1.0 (R3-M2); depth=2 → hops 0,1
   667	        let mut next = Vec::new();
   668	        for fid in &frontier {
   669	            for (caller, edge) in direct_callers(s, fid) {
   670	                if exact_only && edge.confidence != ResolutionConfidence::Exact {
   671	                    continue;
   672	                }
   673	                let (start_byte, end_byte) = function_bytes(s, &caller);
   674	                // One item PER CALL SITE (m7 symmetry with callees); `visited` only gates BFS recursion.
   675	                items.push(EvidenceItem {
   676	                    symbol: Some(SymbolRef::Function {
   677	                        file: caller.file.clone(),
   678	                        name: caller.name.clone(),
   679	                        start_line: caller.start_line,
   680	                        end_line: caller.end_line,
   681	                        start_byte,
   682	                        end_byte,
   683	                        ordinal: 0,
   684	                    }),
   685	                    location: Location {
   686	                        file: caller.file.clone(),
   687	                        start_line: caller.start_line,
   688	                        end_line: caller.end_line,
   689	                        start_byte,
   690	                        end_byte,
   691	                    },
   692	                    score: confidence_score(edge.confidence) / (1.0 + hop as f32),
   693	                    source: Source::PrismCpg,
   694	                    fallback: false,
   695	                    why: vec![Reason::CalledBy {
   696	                        caller: caller.name.clone(),
   697	                        call_site_line: edge.call_site_line,
   698	                    }]
   699	                    .into_iter()
   700	                    .chain(std::iter::once(resolution_reason(edge.kind)))
   701	                    .collect(),
   702	                    snippet: None,
   703	                });
   704	                if visited.insert(caller.clone()) {
   705	                    next.push(caller);
   706	                }
   707	            }
   708	        }
   709	        frontier = next;
   710	    }
   711	    items.sort_by(|a, b| {
   712	        b.score
   713	            .partial_cmp(&a.score)
