   138	    /// Forward reachability following only edges that match the filter.
   139	    ///
   140	    /// Returns all nodes reachable from `start` by traversing edges where
   141	    /// `edge_filter` returns true.
   142	    pub fn reachable_forward(
   143	        &self,
   144	        start: NodeIndex,
   145	        edge_filter: &dyn Fn(&CpgEdge) -> bool,
   146	    ) -> BTreeSet<NodeIndex> {
   147	        let mut visited = BTreeSet::new();
   148	        let mut queue = VecDeque::new();
   149	        queue.push_back(start);
   150	
   151	        while let Some(node) = queue.pop_front() {
   152	            if !visited.insert(node) {
   153	                continue;
   154	            }
   155	            for edge in self.graph.edges(node) {
   156	                if edge_filter(edge.weight()) && !visited.contains(&edge.target()) {
   157	                    queue.push_back(edge.target());
   158	                }
   159	            }
   160	        }
   161	
   162	        visited.remove(&start);
   163	        visited
   164	    }
