   166	    /// Backward reachability following only edges whose reverse matches the filter.
   167	    ///
   168	    /// Uses petgraph's `edges_directed(Incoming)` to walk backward.
   169	    pub fn reachable_backward(
   170	        &self,
   171	        start: NodeIndex,
   172	        edge_filter: &dyn Fn(&CpgEdge) -> bool,
   173	    ) -> BTreeSet<NodeIndex> {
   174	        let mut visited = BTreeSet::new();
