   245	
   246	    /// BFS with hop tracking. Returns (node_index, hop_distance) for all
   247	    /// reachable nodes within `max_hops`, following filtered edges.
   248	    pub fn bfs_with_distance(
   249	        &self,
   250	        starts: &[NodeIndex],
   251	        max_hops: usize,
   252	        edge_filter: &dyn Fn(&CpgEdge) -> bool,
   253	    ) -> BTreeMap<NodeIndex, usize> {
   254	        let mut distances: BTreeMap<NodeIndex, usize> = BTreeMap::new();
   255	        let mut queue: VecDeque<(NodeIndex, usize)> = VecDeque::new();
   256	
   257	        for &start in starts {
   258	            distances.insert(start, 0);
   259	            queue.push_back((start, 0));
   260	        }
   261	
   262	        while let Some((node, hop)) = queue.pop_front() {
   263	            if hop >= max_hops {
   264	                continue;
   265	            }
   266	            let next_hop = hop + 1;
   267	
   268	            for edge in self.graph.edges(node) {
   269	                if edge_filter(edge.weight()) {
   270	                    let target = edge.target();
   271	                    if !distances.contains_key(&target) || distances[&target] > next_hop {
   272	                        distances.insert(target, next_hop);
   273	                        queue.push_back((target, next_hop));
   274	                    }
   275	                }
   276	            }
   277	        }
   278	
   279	        distances
   280	    }
