   285	
   286	    /// Find all nodes on any path from source to sink, following filtered edges.
   287	    pub fn chop(
   288	        &self,
   289	        sources: &[NodeIndex],
   290	        sinks: &[NodeIndex],
   291	        edge_filter: &dyn Fn(&CpgEdge) -> bool,
   292	    ) -> BTreeSet<NodeIndex> {
   293	        let mut forward_set = BTreeSet::new();
   294	        for &src in sources {
   295	            forward_set.extend(self.reachable_forward(src, edge_filter));
   296	            forward_set.insert(src);
   297	        }
   298	
   299	        let mut backward_set = BTreeSet::new();
   300	        for &sink in sinks {
   301	            backward_set.extend(self.reachable_backward(sink, edge_filter));
   302	            backward_set.insert(sink);
   303	        }
   304	
   305	        forward_set.intersection(&backward_set).copied().collect()
   306	    }
