   451	    fn bfs_interproc(
   452	        &self,
   453	        seed: NodeIndex,
   454	        max_depth: usize,
   455	        filter: ConfidenceFilter,
   456	        forward: bool,
   457	    ) -> Vec<(NodeIndex, usize)> {
   458	        let mut result = Vec::new();
   459	        let mut visited: BTreeSet<NodeIndex> = BTreeSet::new();
   460	        let mut queue: VecDeque<(NodeIndex, usize)> = VecDeque::new();
   461	        queue.push_back((seed, 0));
   462	        visited.insert(seed);
   463	
   464	        while let Some((node, depth)) = queue.pop_front() {
   465	            if depth > 0 {
   466	                result.push((node, depth));
   467	            }
   468	
   469	            if depth >= max_depth {
   470	                continue;
   471	            }
